import * as THREE from 'three/webgpu';
import { color, uniform, vec2, vec3, float, mix, smoothstep, length, positionLocal, uv, abs, max, mod, step } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'rich-empty-state';
  const pos = config.scenePosition?.position ?? [0, 0, 0];
  const rot = config.scenePosition?.rotation ?? [0, 0, 0];
  const scl = config.scenePosition?.scale ?? [1, 1, 1];
  group.position.set(...pos);
  group.rotation.set(...rot);
  group.scale.set(...scl);

  const PANEL_W = 3.2;
  const PANEL_H = 2.2;

  // --- Panel background with radial engineered gradient + hairline grid ---
  const panelGeo = new THREE.PlaneGeometry(PANEL_W, PANEL_H, 1, 1);
  const panelMat = new THREE.MeshStandardNodeMaterial();

  const uvNode = uv();
  const centered = uvNode.sub(vec2(0.5, 0.5));
  const dist = length(vec2(centered.x.mul(PANEL_W), centered.y.mul(PANEL_H)));
  const maxDist = float(Math.sqrt((PANEL_W * 0.5) ** 2 + (PANEL_H * 0.5) ** 2));
  const t = dist.div(maxDist).clamp(0.0, 1.0);

  const gradInner = color(0x14141a);
  const gradOuter = color(0x0b0b10);
  const gradientColor = mix(gradInner, gradOuter, t);

  // hairline grid at 0.25 unit pitch, 6% opacity in paper color
  const pitch = float(0.25);
  const scaledUvX = uvNode.x.mul(PANEL_W).div(pitch);
  const scaledUvY = uvNode.y.mul(PANEL_H).div(pitch);
  const gridX = abs(mod(scaledUvX, 1.0).sub(0.5));
  const gridY = abs(mod(scaledUvY, 1.0).sub(0.5));
  const lineWidth = float(0.02);
  const lineX = step(gridX, lineWidth);
  const lineY = step(gridY, lineWidth);
  const gridMask = max(lineX, lineY).mul(0.06);
  const paperColor = color(0xe8ecf2);
  const withGrid = mix(gradientColor, paperColor, gridMask);

  panelMat.colorNode = withGrid;
  panelMat.roughness = 0.7;
  panelMat.metalness = 0.15;

  const panelMesh = new THREE.Mesh(panelGeo, panelMat);
  panelMesh.position.z = 0;
  group.add(panelMesh);

  // hairline border
  const borderGeo = new THREE.EdgesGeometry(new THREE.PlaneGeometry(PANEL_W, PANEL_H));
  const borderMat = new THREE.LineBasicMaterial({ color: 0x26262f });
  const border = new THREE.LineSegments(borderGeo, borderMat);
  border.position.z = 0.001;
  group.add(border);

  // --- Ghost preview: wireframe watch-card outline at left of center ---
  const ghostGroup = new THREE.Group();
  ghostGroup.position.set(-0.75, 0.05, 0.002);

  const ghostMat = new THREE.LineBasicMaterial({ color: 0xe8ecf2, transparent: true, opacity: 0.3 });

  const cardGeo = new THREE.EdgesGeometry(new THREE.PlaneGeometry(1.1, 1.4));
  const cardOutline = new THREE.LineSegments(cardGeo, ghostMat);
  ghostGroup.add(cardOutline);

  const dialGeo = new THREE.RingGeometry(0.27, 0.275, 32);
  const dialMat = new THREE.MeshBasicMaterial({ color: 0xe8ecf2, transparent: true, opacity: 0.22, side: THREE.DoubleSide });
  const dial = new THREE.Mesh(dialGeo, dialMat);
  dial.position.set(0, 0.15, 0);
  ghostGroup.add(dial);

  const barMat = new THREE.MeshBasicMaterial({ color: 0xe8ecf2, transparent: true, opacity: 0.22 });
  const bar1 = new THREE.Mesh(new THREE.PlaneGeometry(0.7, 0.06), barMat);
  bar1.position.set(0, -0.35, 0);
  ghostGroup.add(bar1);
  const bar2 = new THREE.Mesh(new THREE.PlaneGeometry(0.7, 0.06), barMat.clone());
  bar2.position.set(0, -0.5, 0);
  ghostGroup.add(bar2);

  group.add(ghostGroup);

  // breathing animation for ghost group materials
  const ghostMaterials = [ghostMat, dialMat, barMat, bar2.material];
  const breatheState = { v: 0.24 };
  const breatheTween = gsap.to(breatheState, {
    v: 0.34,
    duration: 2.4,
    ease: 'cubic-bezier(0.445, 0.05, 0.55, 0.95)',
    yoyo: true,
    repeat: -1,
    onUpdate: () => {
      ghostMat.opacity = breatheState.v;
      dialMat.opacity = breatheState.v * 0.73;
      barMat.opacity = breatheState.v * 0.73;
      bar2.material.opacity = breatheState.v * 0.73;
    }
  });

  // --- Copy column: headline + body ---
  const textOriginX = -0.05;
  const textOriginY = 0.55;

  const headlineText = ctx.fontAtlas.createText({
    text: 'Your ledger is empty.',
    font: 'Lora',
    fontWeight: 600,
    fontSize: 0.24,
    color: 0xe8ecf2,
    letterSpacing: -0.01,
    lineHeight: 1.15,
    maxWidth: 1.5
  });
  headlineText.position.set(textOriginX, textOriginY, 0.003);
  group.add(headlineText);

  const bodyText = ctx.fontAtlas.createText({
    text: 'Commissioned pieces and saved references will appear here once you begin.',
    font: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 0.1,
    color: 0xc7cbd3,
    letterSpacing: 0,
    lineHeight: 1.5,
    maxWidth: 1.5
  });
  bodyText.position.set(textOriginX, textOriginY - 0.35, 0.003);
  group.add(bodyText);

  // --- Accent CTA button ---
  const ctaGroup = new THREE.Group();
  ctaGroup.position.set(textOriginX + 0.05, textOriginY - 0.85, 0.003);

  const ctaW = 1.5;
  const ctaH = 0.36;
  const ctaGeo = new THREE.PlaneGeometry(ctaW, ctaH);
  const ctaMat = new THREE.MeshStandardNodeMaterial();

  const ctaUv = uv();
  const ctaTop = color(0xff4450);
  const ctaBottom = color(0xc1121f);
  ctaMat.colorNode = mix(ctaBottom, ctaTop, ctaUv.y);
  ctaMat.emissive = new THREE.Color(0xff2a38);
  ctaMat.emissiveIntensity = 1.5;
  ctaMat.roughness = 0.5;
  ctaMat.metalness = 0.3;

  const ctaMesh = new THREE.Mesh(ctaGeo, ctaMat);
  ctaGroup.add(ctaMesh);

  const ctaLabel = ctx.fontAtlas.createText({
    text: 'BROWSE THE COLLECTION',
    font: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 0.05,
    color: 0x16161d,
    letterSpacing: 0.08,
    lineHeight: 1,
    align: 'center'
  });
  ctaLabel.position.set(0, 0, 0.002);
  ctaGroup.add(ctaLabel);

  group.add(ctaGroup);

  // --- Mount animation: fade-up ---
  const mountState = { opacity: 0, y: 0.2 };
  const baseY = group.position.y;
  group.position.y = baseY + mountState.y;
  const setGroupOpacity = (val) => {
    panelMat.opacity = val;
    panelMat.transparent = val < 1;
    ctaMat.opacity = val;
    ctaMat.transparent = val < 1;
    if (headlineText.material) {
      headlineText.material.opacity = val;
      headlineText.material.transparent = val < 1;
    }
    if (bodyText.material) {
      bodyText.material.opacity = val;
      bodyText.material.transparent = val < 1;
    }
    if (ctaLabel.material) {
      ctaLabel.material.opacity = val;
      ctaLabel.material.transparent = val < 1;
    }
  };
  setGroupOpacity(0);

  const mountTween = gsap.to(mountState, {
    opacity: 1,
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
    onUpdate: () => {
      setGroupOpacity(mountState.opacity);
      group.position.y = baseY + mountState.y;
    }
  });

  // --- Press interaction handler ---
  let pressTween = null;
  const handlePressDown = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(ctaGroup.scale, {
      x: 0.97, y: 0.97, z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)'
    });
  };
  const handlePressUp = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(ctaGroup.scale, {
      x: 1, y: 1, z: 1,
      duration: 0.12,
      ease: 'back.out(1.7)'
    });
  };
  const handleClick = () => {
    // navigate: hub-home -> hub-collection
    if (typeof ctx.navigate === 'function') {
      ctx.navigate('hub-collection');
    }
  };

  group.userData.handlers = {
    pointerdown: handlePressDown,
    pointerup: handlePressUp,
    click: handleClick
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    breatheTween.kill();
    mountTween.kill();
    if (pressTween) pressTween.kill();

    panelGeo.dispose();
    panelMat.dispose();
    borderGeo.dispose();
    borderMat.dispose();
    cardGeo.dispose();
    ghostMat.dispose();
    dialGeo.dispose();
    dialMat.dispose();
    bar1.geometry.dispose();
    barMat.dispose();
    bar2.geometry.dispose();
    bar2.material.dispose();
    ctaGeo.dispose();
    ctaMat.dispose();

    if (headlineText.geometry) headlineText.geometry.dispose();
    if (headlineText.material) headlineText.material.dispose();
    if (bodyText.geometry) bodyText.geometry.dispose();
    if (bodyText.material) bodyText.material.dispose();
    if (ctaLabel.geometry) ctaLabel.geometry.dispose();
    if (ctaLabel.material) ctaLabel.material.dispose();
  };

  return group;
}
